import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        if response.status_code != 200:
            raise Exception("Invalid URL or cannot access the URL")
        data = response.json()
        if not data or (isinstance(data, list) and len(data) == 0) or (isinstance(data, dict) and len(data) == 0):
            raise Exception("Empty data or invalid data")
        df = pd.DataFrame(data)
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical characteristics found")
        corr = numeric_df.corr()
        ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
        return df, ax
    except requests.exceptions.RequestException:
        raise Exception("Invalid URL or cannot access the URL")
    except (ValueError, TypeError, KeyError):
        raise Exception("Invalid data")

