import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    def clean(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                new_dict[k] = clean(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                new_list.append(clean(item))
            return new_list
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    data = json.loads(json_str)
    cleaned = clean(data)

    def flatten(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(flatten(item))
        else:
            values.append(obj)
        return values

    all_values = flatten(cleaned)
    value_counts = Counter(all_values)

    return {"data": cleaned, "value_counts": value_counts}

