        current = current[key]
    if isinstance(current, str):
        if current.strip() == '':
            raise ValueError("Data string is empty")
        try:
            current = json.loads(current)
        except json.JSONDecodeError:
            current = [float(x) for x in current.split()]
    if not isinstance(current, list) or len(current) == 0:
        raise ValueError("No numeric data found or data is corrupted")
    try:
